// Fonction pour obtenir tous les cas d'usage d'un secteur
export function getCaseStudiesBySector(sector) {
  return caseStudies.filter(cs => cs.sector === sector)
}

// Fonction pour obtenir un cas d'usage par slug
export function getCaseStudyBySlug(slug) {
  return caseStudies.find(cs => cs.slug === slug)
}

// Fonction pour obtenir tous les secteurs uniques
export function getAllSectors() {
  return [...new Set(caseStudies.map(cs => cs.sector))]
}

// Fonction pour obtenir les cas d'usage les plus pertinents (pour suggestions)
export function getRelatedCaseStudies(currentSlug, limit = 3) {
  const current = getCaseStudyBySlug(currentSlug)
  if (!current) return []
  
  return caseStudies
    .filter(cs => cs.slug !== currentSlug && cs.sector === current.sector)
    .slice(0, limit)
}

// Fonction pour convertir un nom de secteur en slug URL-friendly
export function sectorToSlug(sector) {
  if (!sector) return ''
  const sectorMap = {
    'Immobilier': 'immobilier',
    'Artisanat': 'artisanat',
    'Santé': 'sante',
    'Finance': 'finance',
    'E-commerce': 'e-commerce',
    'Restauration': 'restauration',
    'Éducation': 'education',
    'Sport & Loisirs': 'sport-loisirs',
    'Beauté & Bien-être': 'beaute-bien-etre',
    'Automobile': 'automobile',
    'Hôtellerie': 'hotellerie',
    'Juridique': 'juridique',
    'Immobilier Professionnel': 'immobilier-professionnel',
    'Transport & Logistique': 'transport-logistique',
  }
  if (sectorMap[sector]) return sectorMap[sector]
  return sector.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
}

// Fonction pour obtenir un secteur depuis son slug
export function slugToSector(slug) {
  const sectorMap = {
    'immobilier': 'Immobilier',
    'artisanat': 'Artisanat',
    'sante': 'Santé',
    'finance': 'Finance',
    'e-commerce': 'E-commerce',
    'restauration': 'Restauration',
    'education': 'Éducation',
    'sport-loisirs': 'Sport & Loisirs',
    'beaute-bien-etre': 'Beauté & Bien-être',
    'automobile': 'Automobile',
    'hotellerie': 'Hôtellerie',
    'juridique': 'Juridique',
    'immobilier-professionnel': 'Immobilier Professionnel',
    'transport-logistique': 'Transport & Logistique',
  }
  return sectorMap[slug] || null
}
